        --bg: #080b12;
        --panel: #111827;
        --panel-strong: #172033;
        --text: #f4f7fb;
        --muted: #bdc8d8;
        --accent: #8bd3ff;
        --accent-strong: #b794ff;
        --border: #334155;
        --focus: #facc15;
        --shadow: #000000;
