        scroll-behavior: smooth;
      }

      body {
        min-width: 320px;
        margin: 0;
        font-family:
          Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
          "Segoe UI", sans-serif;
        line-height: 1.6;
        color: var(--text);
        background:
