        font-size: 0.82rem;
        font-weight: 800;
        letter-spacing: 0.14em;
        text-transform: uppercase;
      }

      h1 {
        margin: 0;
        font-size: clamp(2.4rem, 8vw, 5rem);
        line-height: 1;
        letter-spacing: -0.06em;
      }

      .intro {
        max-width: 44rem;
        margin: 1rem auto 0;
        color: var(--muted);
        font-size: 1.125rem;
      }

      .faq-list {
        display: grid;
        gap: 1rem;
      }

      .example {
        overflow: hidden;
        border: 1px solid var(--border);
        border-radius: 1.25rem;
        background:
          linear-gradient(145deg, var(--panel-strong), var(--panel));
        box-shadow: 0 1.5rem 3.5rem var(--shadow);
      }

      .question {
        width: 100%;
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 1rem;
        border: 0;
        padding: 1.25rem;
